const input = $input.first().json;
const body = input.body ?? input;

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function timestamp() {
  return new Date().toISOString().replace(/[:.]/g, '-');
}

function safeFilename(value) {
  const fallback = `pdfbolt-template-document-${timestamp()}.pdf`;
  const raw = String(value || fallback).trim();
  const cleaned = raw
    .replace(/[^a-zA-Z0-9._-]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 120);

  const filename = cleaned || fallback;
  return filename.toLowerCase().endsWith('.pdf') ? filename : `${filename}.pdf`;
}

const errors = [];
const templateData = isPlainObject(body.templateData) ? body.templateData : {};

// Required: data for the PDFBolt template and email address for Gmail
if (!isPlainObject(body)) {
  errors.push('Request body must be a JSON object.');
}

if (Object.keys(templateData).length === 0) {
  errors.push('Missing required field: templateData.');
}

const recipientEmail = String(body.recipientEmail || '').trim();

if (!recipientEmail) {
  errors.push('Missing required field: recipientEmail.');
}

// Optional fields used for the email and generated PDF filename
const filename = safeFilename(body.filename);
const recipientName = String(body.recipientName || 'there').trim();
const emailSubject = String(body.emailSubject || `Your PDF document: ${filename}`).trim();
const emailMessage = String(
  body.emailMessage ||
  `Hi ${recipientName},

Please find your PDF document attached.

Thank you.`
).trim();
const status = errors.length === 0 ? 'valid' : 'invalid';

return [{
  json: {
    valid: status === 'valid',
    status,
    errors,
    templateData,
    filename,
    recipientEmail,
    recipientName,
    emailSubject,
    emailMessage,
    receivedFields: isPlainObject(body) ? Object.keys(body) : [],
  },
}];
